import {createGoblins} from './goblin-model.js';

export function makeGoblins(THREE,root,site,register){
 const population=new THREE.Group();root.add(population);
 const model=createGoblins(Math.abs(site.x*37+site.z)),actors=[],occluders=[],sphere=new THREE.SphereGeometry(1,32,24),limb=new THREE.CylinderGeometry(.085,.12,.48,24,3);
 const mat=color=>new THREE.MeshStandardMaterial({color,roughness:.82}),dark=mat(0x302f33),eye=mat(0xf4dc9a),leather=mat(0x6a4837),metal=mat(0xab9765);
 function part(parent,geometry,material,x,y,z,sx=1,sy=1,sz=1){const mesh=new THREE.Mesh(geometry,material);mesh.position.set(x,y,z);mesh.scale.set(sx,sy,sz);parent.add(mesh);occluders.push(mesh);return mesh;}
 function bubble(text){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=96;const ctx=canvas.getContext('2d');ctx.fillStyle='#172827e6';ctx.beginPath();ctx.roundRect(2,2,508,90,24);ctx.fill();ctx.font='24px sans-serif';ctx.textAlign='center';ctx.fillStyle='#f6e8ca';ctx.fillText(text,256,57);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(canvas),depthWrite:false}));sprite.scale.set(3.4,.64,1);sprite.position.y=2.75;return sprite;}
 for(const g of model.goblins){const actor=new THREE.Group();actor.userData.character=true;population.add(actor);const body=new THREE.Group();actor.add(body);const skin=mat([0x8aa26a,0x6f966e,0x9dac73,0x6b9d88][g.index%4]),cloth=mat([0x856572,0x71617e,0x9f784c,0x507c83][g.index%4]);part(body,sphere,cloth,0,1.04,0,.34,.43,.23);part(body,sphere,leather,0,.8,0,.36,.11,.25);part(body,sphere,metal,.04,.82,.25,.075,.08,.035);
 const head=part(body,sphere,skin,0,1.68,.02,.34,.33,.28);register(head,site,'greet',`Conversar com ${g.name}`,g.index);for(const side of [-1,1]){const ear=part(body,sphere,skin,side*.39,1.73,.01,.25,.095,.09);ear.rotation.z=side*.33;part(body,sphere,eye,side*.125,1.72,.265,.083,.061,.035);part(body,sphere,dark,side*.125,1.72,.298,.027,.04,.018);const brow=part(body,sphere,skin,side*.13,1.79,.265,.12,.045,.04);brow.rotation.z=side*-.15;}part(body,sphere,skin,0,1.61,.31,.12,.105,.16);part(body,sphere,dark,0,1.5,.256,.11,.02,.025);
 const legs=[],arms=[];for(const side of [-1,1]){const hip=new THREE.Group();hip.position.set(side*.18,.77,0);actor.add(hip);part(hip,limb,cloth,0,-.22,0,1,1,1);part(hip,sphere,leather,0,-.61,.075,.135,.13,.23);part(hip,limb,skin,0,-.48,0,.76,.4,.76);legs.push(hip);const shoulder=new THREE.Group();shoulder.position.set(side*.35,1.28,0);body.add(shoulder);part(shoulder,limb,cloth,side*.05,-.18,0,.9,.8,.9);part(shoulder,limb,skin,side*.07,-.46,.03,.7,.65,.7);part(shoulder,sphere,skin,side*.07,-.64,.04,.1,.13,.085);shoulder.rotation.z=side*.12;arms.push(shoulder);}
 const speech=bubble(['Olha! Outra pedrinha brilhante!','Os cristais cantaram hoje!','Pedra sem brilho? Que bobagem.','A pedra violeta respondeu.'][g.index%4]);actor.add(speech);speech.visible=false;actors.push({actor,body,legs,arms,speech});}
 function update(dt,camera,room){if(camera)population.visible=room?.id===site.id||camera.position.distanceTo(root.position)<140;model.update(dt);for(const g of model.goblins){const a=actors[g.index],time=model.time,gait=g.distance*7;a.actor.position.set(g.x,g.y,g.z);a.actor.rotation.y=g.heading;a.body.position.y=g.moving?Math.abs(Math.sin(gait))*.035:Math.sin(time*1.8+g.index)*.012;a.legs.forEach((leg,i)=>leg.rotation.x=g.moving?Math.sin(gait+i*Math.PI)*.38:0);const talking=g.mode==='chat',speaking=talking&&Math.floor(time/2)%2===(g.index<g.partner?0:1);a.arms.forEach((arm,i)=>{arm.rotation.x=g.moving?-Math.sin(gait+i*Math.PI)*.3:speaking?-.5+Math.sin(time*4+i)*.15:0;arm.rotation.z=(i?1:-1)*.12;if(g.mode==='greet'&&i===1){arm.rotation.z=-2.3+Math.sin(time*5)*.23;arm.rotation.x=-.4;}});if(g.mode==='admire'){a.arms[1].rotation.x=-.65;a.body.rotation.x=.1;}else a.body.rotation.x=0;a.speech.visible=speaking;}}
 update(0);return{occluders,update,greet(index){model.greet(index);return model.goblins[index]?.name||'Goblin';}};
}
